import React, { useState, useEffect } from 'react';

const SiteStatisticsTab = () => {
  // 가상의 통계 데이터 (실제로는 백엔드에서 가져올 데이터)
  const [statistics, setStatistics] = useState({
    totalMembers: 0,
    totalPosts: 0,
    totalComments: 0,
  });

  useEffect(() => {
    // 실제 통계 데이터 API 호출
    // fetch('/api/admin/statistics')
    //   .then(res => res.json())
    //   .then(data => setStatistics(data))
    //   .catch(error => console.error('통계 데이터 로딩 실패:', error));

    // 가상 데이터 로드
    setTimeout(() => {
      setStatistics({
        totalMembers: 1234,
        totalPosts: 567,
        totalComments: 890,
      });
    }, 500); // 0.5초 지연 시뮬레이션
  }, []);

  return (
    <div className="tab-content-section site-statistics-tab">
      <h3 className="tab-content-title">사이트 통계 📊</h3>
      <div className="statistic-cards">
        <div className="statistic-card">
          <h4>총 회원 수</h4>
          <div className="statistic-value">{statistics.totalMembers.toLocaleString()}</div>
          <p className="statistic-description">현재 가입된 회원 수</p>
        </div>
        <div className="statistic-card">
          <h4>총 게시글 수</h4>
          <div className="statistic-value">{statistics.totalPosts.toLocaleString()}</div>
          <p className="statistic-description">전체 게시판에 작성된 게시글 수</p>
        </div>
        <div className="statistic-card">
          <h4>총 댓글 수</h4>
          <div className="statistic-value">{statistics.totalComments.toLocaleString()}</div>
          <p className="statistic-description">전체 게시글에 달린 댓글 수</p>
        </div>
      </div>
    </div>
  );
};

export default SiteStatisticsTab;
